setupCode:
@use '@angular/material' as mat;

$my-primary: mat.$violet-palette;
$my-tertiary: mat.$blue-palette;

html {
  @include mat.theme((
    color: (
      primary: $my-primary,
      tertiary: $my-tertiary,
    ),
    typography: Roboto,
    density: 0,
  ));
}

// Override an individual system token for a one-off deviation.
html {
  --mat-sys-primary: #6750a4;
}
